package glitch

import data.glitch_lib

# Patterns for credential-related field names - excluding storage locations like keystore, truststore
credential_patterns := {"password", "passwd", "pwd", "secret", "token", "credential", "pass"}

# Patterns to exclude - these are typically storage locations, not credential values
exclude_patterns := {"keystore", "truststore", "storetype", "storepass", "keypass", "cert", "certificate", "ca_file", "cert_file", "key_file", "path", "file", "dir", "directory", "location", "uri", "url"}

# Common weak/default passwords
weak_passwords := {"admin", "password", "123456", "default", "secret", "root", "changeme", "todo", "fixme", "test", "pass", "pass123", "welcome", "guest", "user", "login"}

# Check if a field name matches credential patterns but isn't a storage location
is_credential_field(name) {
    lower_name := lower(name)
    pattern := credential_patterns[_]
    contains(lower_name, pattern)
    not is_storage_location(lower_name)
}

# Check if name indicates a storage location rather than a credential value
is_storage_location(name) {
    exclude := exclude_patterns[_]
    contains(name, exclude)
}

# Check if a string value is a weak/default password
is_weak_password(value) {
    lower_val := lower(value)
    weak_passwords[lower_val]
} else {
    # Check for common patterns in weak passwords
    regex.match("^(?:x{3,}|\\*{3,}|0{3,}|1{3,}|_{3,})$", lower(value))
}

# Check if value is a literal string (not a variable reference or external source)
is_literal_string(value) {
    value.ir_type == "String"
    not contains(value.value, "${")
    not contains(value.value, "{{")
    not contains(value.value, "$(")
}

# Check if value looks like a hash/encrypted password (starts with $)
is_hashed_password(value) {
    regex.match("^\\$[0-9a-zA-Z]+\\$", value)
}

# Check if value looks like base64 encoded data
is_base64_like(value) {
    regex.match("^[A-Za-z0-9+/]{16,}={0,2}$", value)
}

# Recursively find credential fields in any value structure (Hash, Array, nested)
find_credential_fields(value, key_name, path, results) = results {
    # Handle Hash: recurse into each key-value pair
    value.ir_type == "Hash"
    all_results := {r |
        some i
        kv := value.value[i]
        next_key := get_string_value(kv.key)
        next_value := kv.value
        qualified_key := qualify_key(key_name, next_key)
        nested := find_credential_fields(next_value, qualified_key, array.concat(path, [qualified_key]), [])
        r := nested[_]
    }
    results := all_results
} else = results {
    # Handle Array: recurse into each element
    value.ir_type == "Array"
    all_results := {r |
        some i
        elem := value.value[i]
        nested := find_credential_fields(elem, key_name, array.concat(path, [i]), [])
        r := nested[_]
    }
    results := all_results
} else = {{ "key": key_name, "value": value, "path": path }} {
    # Leaf node: check if current key is a credential field and value is a literal string
    value.ir_type == "String"
    is_credential_field(key_name)
    not is_storage_path(value.value)
} else = {{ "key": key_name, "value": value, "path": path }} {
    # Also detect if key is credential field and value is base64-like (likely encoded password)
    value.ir_type == "String"
    is_credential_field(key_name)
    is_base64_like(value.value)
} else = set() {
    true
}

# Helper to get string value safely
get_string_value(node) = node.value {
    node.ir_type == "String"
} else = "" {
    true
}

# Build qualified key name
qualify_key(base, next) = next {
    base == ""
} else = sprintf("%s.%s", [base, next]) {
    true
}

# Check if value looks like a file path rather than a credential
is_storage_path(value) {
    regex.match("^[.\\/]+[a-zA-Z_/\\.\\-]+$", value)
} else {
    regex.match("^[a-zA-Z_]+[a-zA-Z0-9_]*_path$", lower(value))
}

# Detect credentials in nested variable values
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # Recursively find credential fields in the variable's value
    findings := find_credential_fields(var.value, var.name, [var.name], [])
    finding := findings[_]

    # Ensure we have a valid finding with a string value
    finding.value.ir_type == "String"

    # Skip if it looks like a file path
    not is_storage_path(finding.value.value)

    result := {
        "type": "sec_hard_pass",
        "element": finding.value,
        "path": parent.path,
        "description": "Use of hard-coded password - Credentials should not be hardcoded in configuration files. Use secret management systems instead. (CWE-259)"
    }
}

# Detect weak passwords in nested structures
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    findings := find_credential_fields(var.value, var.name, [var.name], [])
    finding := findings[_]

    finding.value.ir_type == "String"
    is_weak_password(finding.value.value)

    result := {
        "type": "sec_hard_pass", 
        "element": finding.value,
        "path": parent.path,
        "description": "Use of hard-coded password - Weak or default password detected. Use secret management systems instead. (CWE-259)"
    }
}

# Detect hashed/encrypted passwords (still hardcoded)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    findings := find_credential_fields(var.value, var.name, [var.name], [])
    finding := findings[_]

    finding.value.ir_type == "String"
    is_hashed_password(finding.value.value)

    result := {
        "type": "sec_hard_pass",
        "element": finding.value,
        "path": parent.path,
        "description": "Use of hard-coded password - Hashed password is still hardcoded. Use secret management systems instead. (CWE-259)"
    }
}

# Detect credentials in atomic unit attributes (also nested)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    findings := find_credential_fields(attr.value, attr.name, [attr.name], [])
    finding := findings[_]

    finding.value.ir_type == "String"
    not is_storage_path(finding.value.value)

    result := {
        "type": "sec_hard_pass",
        "element": finding.value,
        "path": parent.path,
        "description": "Use of hard-coded password - Credentials should not be hardcoded in configuration files. Use secret management systems instead. (CWE-259)"
    }
}

# Direct attribute detection for simple credential fields
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_credential_field(attr.name)
    attr.value.ir_type == "String"
    not is_storage_path(attr.value.value)
    not contains(attr.value.value, "${")
    not contains(attr.value.value, "{{")

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded password - Credentials should not be hardcoded in configuration files. Use secret management systems instead. (CWE-259)"
    }
}

